cd /tmp && cat > pyrepr.js <<'EOF'
function pyrepr(x){
  if (Object.is(x,-0)) return '-0.0';
  if (x===0) return '0.0';
  const m=/^(\d)(?:\.(\d+))?e([+-]\d+)$/.exec(Math.abs(x).toExponential());
  const D=m[1]+(m[2]||''); const E=parseInt(m[3]);
  let s;
  if (E<-4||E>=16) s=D[0]+(D.length>1?'.'+D.slice(1):'')+'e'+(E<0?'-':'+')+String(Math.abs(E)).padStart(2,'0');
  else if (E>=0) s = D.length<=E+1 ? D+'0'.repeat(E+1-D.length)+'.0' : D.slice(0,E+1)+'.'+D.slice(E+1);
  else s='0.'+'0'.repeat(-E-1)+D;
  return (x<0?'-':'')+s;
}
module.exports={pyrepr};
if(require.main===module){
  const v=process.argv[2];
  const n=Number(v);
  if(!Number.isFinite(n)) { console.log('NONFINITE'); } else console.log("b'"+pyrepr(n)+"'");
}
EOF
