// exact decimal string of m * 2^e  (m BigInt, e int)
function exactDec(m,e){
  if(e>=0) return (m<<BigInt(e)).toString();
  const k=-e;
  // m/2^k = m*5^k / 10^k
  let num=m*(5n**BigInt(k));
  let s=num.toString();
  if(s.length<=k) s='0'.repeat(k-s.length+1)+s;
  const ip=s.slice(0,s.length-k), fp=s.slice(s.length-k).replace(/0+$/,'');
  return fp? ip+'.'+fp : ip;
}
const args=process.argv.slice(2);
console.log(exactDec(BigInt(args[0]),parseInt(args[1])));
